import RNA
import random
random.seed(42)

target = "(.(((..(((((....(((((......))))))))))((((...((((.....))))))))(((..(((....)))))).(((...((((...((((......))))))))(((..(((.....))))))((.((....)))).((((....(((..(((......))))))((.((.....))))(((....))).(((((.....((.((......))))(((.....)))((....)).((((((......(((......)))((.....))...(((((((...))))))).......))))))......))))).....))))....)))...)))..)...(.((.((((....((....))((....))((((((...)))))).)))))).)"
N = len(target)

pairs = {}
stack = []
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j = stack.pop()
        pairs[j]=i
        pairs[i]=j

def get_pairs(ss):
    p=set(); st=[]
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')': p.add((st.pop(), i))
    return p

target_pairs = get_pairs(target)

def fold(seq):
    md = RNA.md()
    md.dangles=2
    fc = RNA.fold_compound(seq, md)
    ss, mfe = fc.mfe()
    return ss, mfe

def bp_dist(ss):
    p = get_pairs(ss)
    return len(p ^ target_pairs)

def init_seq():
    seq = ['A']*N
    for i in range(N):
        if i in pairs:
            if i < pairs[i]:
                seq[i]='G'; seq[pairs[i]]='C'
    hairpins = [
        (20,27,6),(47,53,5),(68,73,4),(96,103,6),(118,124,5),
        (134,139,4),(159,166,6),(176,182,5),(188,193,4),(211,218,6),
        (224,230,5),(234,239,4),(256,263,6),(267,273,5),(284,288,3),
        (361,366,4),(369,374,4),(381,385,3),
    ]
    caps={3:"GAA",4:"GAAA",5:"GAAAC",6:"GAAAAC"}
    for (a,b,L) in hairpins:
        loop_seq=caps.get(L)
        if loop_seq:
            for k,ch in enumerate(loop_seq):
                seq[a+1+k]=ch
    return ''.join(seq)

def diagnose(seq, ss):
    """Return missing pairs (in target, not in mfe) and spurious pairs (in mfe, not in target)."""
    cur = get_pairs(ss)
    missing = target_pairs - cur
    spurious = cur - target_pairs
    return missing, spurious

def repair_step(seq):
    seq = list(seq)
    ss, mfe = fold(''.join(seq))
    missing, spurious = diagnose(seq, ss)
    # Strengthen missing pairs -> set G-C
    for (i,j) in missing:
        seq[i]='G'; seq[j]='C'
    # Break spurious pairs -> mismatch
    for (i,j) in spurious:
        # only break if (i,j) is not a target pair
        if (i,j) not in target_pairs and (j,i) not in target_pairs:
            # set one to A, the other to A (mismatch) - but don't destroy target pair at that pos
            # if position i is part of a target pair, keep its partner; break the other
            if i in pairs:
                seq[j]='A'
            elif j in pairs:
                seq[i]='A'
            else:
                seq[i]='A'; seq[j]='A'
    return ''.join(seq), ss, mfe, len(missing), len(spurious)

seq = init_seq()
best = seq
best_dist = bp_dist(fold(seq)[0])
print("init dist:", best_dist)

for it in range(200):
    seq, ss, mfe, nm, ns = repair_step(seq)
    d = bp_dist(ss)
    if d < best_dist:
        best_dist = d
        best = seq
    if d == 0:
        print(f"iter {it}: SOLVED dist=0 mfe={mfe}")
        break
    if it % 20 == 0:
        print(f"iter {it}: dist={d} missing={nm} spurious={ns} mfe={mfe:.1f}")

# final verify
ss, mfe = fold(best)
d = bp_dist(ss)
match = sum(1 for a,b in zip(ss,target) if a==b)
print(f"FINAL: dist={d} match={match}/{N} mfe={mfe:.2f}")
print("SEQ:", best)
